"use client";

import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from "react";
import { LiveRegion } from "@/components/bjork-ui/_core/a11y";
import { easeCss } from "@/components/bjork-ui/_core/motion";
import {
  FOCUS_RING,
  PRESS,
  SHIMMER_TEXT_CSS,
  useAiTone,
  useControllable,
  useReduceMotion,
  type BjorkTone,
} from "@/components/bjork-ui/ai/_shared";
import { StrokeMorphIcon } from "@/components/bjork-ui/utilities/stroke-morph-icon";
import { cn } from "@/lib/utils";

export interface ReasoningDisclosureProps {
  /** The reasoning so far. Pass the full text on every chunk. Blank lines split paragraphs. */
  text: string;
  /** True while reasoning tokens are arriving. The label shimmers and the clock runs. */
  streaming?: boolean;
  /** Epoch milliseconds when reasoning began. Without it, the first streaming render is used. */
  startedAt?: number;
  /** Final reasoning time in milliseconds. Wins over the measured time once streaming ends. */
  durationMs?: number;
  /** Short titles for the reasoning so far, shown as a mini outline. The last one is current while streaming. */
  steps?: string[];
  /** Controlled open state. */
  open?: boolean;
  /** Defaults to open while streaming and closed for a finished message. */
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Fold shut a beat after streaming ends. Default true. */
  autoCollapse?: boolean;
  /** Height of the live viewport while streaming, in pixels. Default 128. */
  maxHeight?: number;
  /** Label while streaming. Default "Thinking". */
  label?: string;
  /** Demo/preview only: freezes the clock. */
  now?: number;
  tone?: BjorkTone;
  className?: string;
}

export const SAMPLE_REASONING = `The user wants the drafts to stop feeling sticky on slow laptops. Typing itself is cheap, so the cost has to be somewhere on the change path.

Looking at the editor wiring: every change event calls persist(), and persist() serialises the whole document and writes it to IndexedDB. On a 40-page draft that is a few milliseconds per keystroke, which is enough to drop frames on a throttled CPU.

Options: throttle the writes, debounce them, or move serialisation to a worker. A trailing debounce is the smallest change. The risk is losing the last edit when the tab closes, so it needs a flush on visibilitychange.

Reads are already served from the in-memory draftStore cache, so they can stay synchronous. I should mention the measured win from the Kestrel Mini rig and keep the answer short.`;

export const SAMPLE_REASONING_STEPS = [
  "Locate the slow path",
  "Weigh throttle, debounce and a worker",
  "Guard against lost edits",
  "Draft the answer",
];

const AUTO_COLLAPSE_MS = 900;
const TICK_MS = 250;

/** 4200 -> "4s", 72000 -> "1m 12s". Whole seconds, never "0s". */
function formatSeconds(ms: number): string {
  const total = Math.max(1, Math.round(ms / 1000));
  if (total < 60) return `${total}s`;
  return `${Math.floor(total / 60)}m ${total % 60}s`;
}

/** Live seconds while streaming count up from zero, so the first second reads "0s" rather than jumping to 1. */
function formatLive(ms: number): string {
  const total = Math.max(0, Math.floor(ms / 1000));
  if (total < 60) return `${total}s`;
  return `${Math.floor(total / 60)}m ${total % 60}s`;
}

/**
 * A model's reasoning as a quiet disclosure. While it streams, the label shimmers, the seconds count up and the text
 * scrolls in a capped viewport. When it ends it becomes "Thought for 12s" and folds away.
 */
export function ReasoningDisclosure({
  text,
  streaming = false,
  startedAt,
  durationMs,
  steps,
  open,
  defaultOpen,
  onOpenChange,
  autoCollapse = true,
  maxHeight = 128,
  label = "Thinking",
  now,
  tone: toneProp,
  className,
}: ReasoningDisclosureProps) {
  const { pal, style } = useAiTone(toneProp);
  const reduce = useReduceMotion();
  const panelId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const viewportRef = useRef<HTMLDivElement>(null);
  const [isOpen, setOpen] = useControllable(open, defaultOpen ?? streaming, onOpenChange);

  // Streaming transitions, derived during render. `finished` is true only when this instance saw streaming end.
  const [phase, setPhase] = useState({ streaming, finished: false, message: "" });
  if (phase.streaming !== streaming) {
    setPhase({
      streaming,
      finished: !streaming,
      message: streaming
        ? `${label}`
        : durationMs !== undefined
          ? `Thought for ${formatSeconds(durationMs)}`
          : "Finished thinking",
    });
  }

  useEffect(() => {
    if (!phase.finished || !autoCollapse) return;
    const id = window.setTimeout(() => setOpen(false), AUTO_COLLAPSE_MS);
    return () => window.clearTimeout(id);
  }, [phase.finished, autoCollapse, setOpen]);

  // The clock. Times live in refs and the seconds are painted straight into the DOM, so ticking never re-renders.
  const startRef = useRef<number | null>(null);
  const endRef = useRef<number | null>(null);
  const latest = useRef({ streaming, startedAt, durationMs, now });

  const paint = useCallback(() => {
    const el = rootRef.current?.querySelector<HTMLElement>("[data-reasoning-clock]");
    if (!el) return;
    const { streaming: live, startedAt: start, durationMs: duration, now: frozen } = latest.current;
    const from = start ?? startRef.current;
    if (live) {
      el.textContent = from === null ? "0s" : formatLive((frozen ?? Date.now()) - from);
      return;
    }
    if (duration !== undefined) el.textContent = formatSeconds(duration);
    else if (from !== null && endRef.current !== null) el.textContent = formatSeconds(endRef.current - from);
    else el.textContent = "a moment";
  }, []);

  useLayoutEffect(() => {
    latest.current = { streaming, startedAt, durationMs, now };
    const clock = now ?? Date.now();
    if (streaming) {
      if (startRef.current === null || endRef.current !== null) startRef.current = clock;
      endRef.current = null;
    } else if (startRef.current !== null && endRef.current === null) {
      endRef.current = clock;
    }
    paint();
  });

  useEffect(() => {
    if (!streaming || now !== undefined) return;
    const id = window.setInterval(paint, TICK_MS);
    return () => window.clearInterval(id);
  }, [streaming, now, paint]);

  // Auto-scroll the live viewport, unless the reader has scrolled up to read something.
  const stickRef = useRef(true);
  useLayoutEffect(() => {
    const el = viewportRef.current;
    if (!el) return;
    if (streaming && stickRef.current) el.scrollTop = el.scrollHeight;
    el.dataset.fade = streaming && el.scrollTop > 2 ? "true" : "false";
  }, [text, streaming, isOpen]);

  const onScroll = () => {
    const el = viewportRef.current;
    if (!el) return;
    stickRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < 8;
    el.dataset.fade = streaming && el.scrollTop > 2 ? "true" : "false";
  };

  const paragraphs = text.split(/\n{2,}/).filter((p) => p.trim() !== "");
  const capped = streaming;

  return (
    <div
      ref={rootRef}
      className={cn("@container w-full max-w-[560px] font-bjork-alpha text-[color:var(--bjork-text)]", className)}
      style={style}
    >
      <style href="bjork-ai-shimmer" precedence="default">
        {SHIMMER_TEXT_CSS}
      </style>

      <button
        type="button"
        aria-expanded={isOpen}
        aria-controls={panelId}
        onClick={() => setOpen(!isOpen)}
        className={cn(
          "group -mx-1.5 inline-flex min-h-8 cursor-pointer items-center gap-1.5 rounded-[8px] px-1.5 text-left",
          FOCUS_RING,
          PRESS,
        )}
      >
        <span className="flex items-baseline gap-1.5 text-[14px] leading-5">
          {streaming ? (
            <span className="bjork-ai-shimmer font-medium">{label}</span>
          ) : (
            <span className="font-medium text-[color:var(--bjork-text-muted)] transition-colors group-hover:text-[color:var(--bjork-text)]">
              Thought for
            </span>
          )}
          {streaming && now !== undefined && startedAt !== undefined ? (
            <span key="frozen" className={clockClass(streaming)}>
              {formatLive(now - startedAt)}
            </span>
          ) : !streaming && durationMs !== undefined ? (
            <span key="final" className={clockClass(streaming)}>
              {formatSeconds(durationMs)}
            </span>
          ) : (
            <span key="live" data-reasoning-clock="" className={clockClass(streaming)} />
          )}
        </span>
        <span
          aria-hidden="true"
          className={cn(
            "grid size-3.5 shrink-0 place-items-center transition-transform duration-[180ms] ease-out motion-reduce:transition-none",
            isOpen ? "rotate-0" : "-rotate-90",
          )}
        >
          <StrokeMorphIcon name="chevron-down" size={12} strokeWidth={1.75} color={pal.textFaint} />
        </span>
      </button>

      <div
        id={panelId}
        role="region"
        aria-label="Reasoning"
        aria-hidden={!isOpen || undefined}
        inert={!isOpen}
        className="grid"
        style={{
          gridTemplateRows: isOpen ? "1fr" : "0fr",
          opacity: isOpen ? 1 : 0,
          transition: reduce ? "none" : `grid-template-rows 280ms ${easeCss.drawer}, opacity 280ms ${easeCss.drawer}`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <div className="ml-[3px] mt-1.5 border-l border-[color:var(--bjork-border)] pl-4">
            {steps && steps.length > 0 && (
              <ol aria-label="Outline" className="mb-2.5 grid gap-1 pt-0.5">
                {steps.map((step, i) => {
                  const current = streaming && i === steps.length - 1;
                  return (
                    <li key={`${i}:${step}`} className="flex min-w-0 items-center gap-2.5 text-[12px] leading-[18px]">
                      <span
                        aria-hidden="true"
                        className={cn(
                          "size-[5px] shrink-0 rounded-full",
                          current ? "bg-[color:var(--bjork-accent)]" : "bg-[color:var(--bjork-text-faint)]",
                        )}
                      />
                      <span
                        className={cn(
                          "min-w-0 truncate",
                          current ? "text-[color:var(--bjork-text-medium)]" : "text-[color:var(--bjork-text-soft)]",
                        )}
                      >
                        {step}
                      </span>
                    </li>
                  );
                })}
              </ol>
            )}
            <div
              ref={viewportRef}
              onScroll={onScroll}
              tabIndex={capped ? 0 : undefined}
              aria-label={capped ? "Reasoning so far" : undefined}
              className={cn(
                "rounded-[4px] text-[13px] leading-5 text-[color:var(--bjork-text-muted)] [overflow-wrap:anywhere]",
                "data-[fade=true]:[mask-image:linear-gradient(to_bottom,transparent,black_28px)]",
                capped && "overflow-y-auto overscroll-contain [scrollbar-width:none]",
                capped && FOCUS_RING,
              )}
              style={capped ? { maxHeight } : undefined}
            >
              {paragraphs.length === 0 && streaming ? (
                <p className="text-[color:var(--bjork-text-faint)]">…</p>
              ) : (
                paragraphs.map((p, i) => (
                  <p key={i} className="mb-2.5 whitespace-pre-wrap last:mb-0">
                    {p}
                  </p>
                ))
              )}
            </div>
          </div>
        </div>
      </div>

      <LiveRegion message={phase.message} />
    </div>
  );
}

function clockClass(streaming: boolean): string {
  return cn(
    "inline-block min-w-[3ch] font-mono text-[12px] tabular-nums",
    streaming ? "text-[color:var(--bjork-text-faint)]" : "text-[color:var(--bjork-text-muted)]",
  );
}

import type { ReactNode } from "react";

// Text for assistive tech only.
export function VisuallyHidden({ children }: { children: ReactNode }) {
  return <span className="sr-only">{children}</span>;
}

// Announces `message` when it changes. Same text re-rendered does not re-announce.
export function LiveRegion({
  message,
  politeness = "polite",
}: {
  message: string;
  politeness?: "polite" | "assertive";
}) {
  return (
    <span role="status" aria-live={politeness} aria-atomic="true" className="sr-only">
      {message}
    </span>
  );
}

// Shared springs, easings and durations. Components import these instead of inventing values.

export const springs = {
  press: { type: "spring", stiffness: 500, damping: 30, mass: 0.6 },
  snappy: { type: "spring", stiffness: 400, damping: 25, mass: 1 },
  standard: { type: "spring", stiffness: 300, damping: 30, mass: 0.8 },
  soft: { type: "spring", stiffness: 200, damping: 25, mass: 1.2 },
  settle: { type: "spring", stiffness: 380, damping: 30, mass: 0.8 },
  blurIn: { type: "spring", stiffness: 400, damping: 28, mass: 0.6 },
} as const;

export const ease = {
  out: [0.23, 1, 0.32, 1],
  inOut: [0.77, 0, 0.175, 1],
  drawer: [0.32, 0.72, 0, 1],
} as const;

export const easeCss = {
  out: "cubic-bezier(0.23,1,0.32,1)",
  inOut: "cubic-bezier(0.77,0,0.175,1)",
  drawer: "cubic-bezier(0.32,0.72,0,1)",
} as const;

export const durations = { press: 140, tooltip: 160, menu: 200, panel: 280 } as const; // ms

// Cubic bezier easing for canvas and rAF code. Returns progress y for input x in [0, 1].
export function cubicBezier(x1: number, y1: number, x2: number, y2: number): (t: number) => number {
  const cx = 3 * x1;
  const bx = 3 * (x2 - x1) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * y1;
  const by = 3 * (y2 - y1) - cy;
  const ay = 1 - cy - by;
  const sampleX = (s: number) => ((ax * s + bx) * s + cx) * s;
  const sampleY = (s: number) => ((ay * s + by) * s + cy) * s;
  const sampleDX = (s: number) => (3 * ax * s + 2 * bx) * s + cx;

  const solveX = (x: number) => {
    let s = x;
    for (let i = 0; i < 8; i++) {
      const err = sampleX(s) - x;
      if (Math.abs(err) < 1e-6) return s;
      const d = sampleDX(s);
      if (Math.abs(d) < 1e-6) break;
      s -= err / d;
    }
    let lo = 0;
    let hi = 1;
    s = x;
    while (lo < hi) {
      const v = sampleX(s);
      if (Math.abs(v - x) < 1e-6) return s;
      if (x > v) lo = s;
      else hi = s;
      s = (lo + hi) / 2;
      if (hi - lo < 1e-7) break;
    }
    return s;
  };

  return (t: number) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    return sampleY(solveX(t));
  };
}

"use client";

// Shared plumbing for the bjork-ui AI components: tone tokens, reduced motion, controllable state and
// number formatting. Every AI component imports from here so they read as one family.

import {
  useCallback,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
} from "react";
import { useReducedMotion } from "framer-motion";
import { BJORK_PALETTE, type BjorkTone } from "@/components/bjork-ui/_core/palette";
import { useBjorkTone } from "@/components/bjork-ui/_core/tone";

export type { BjorkTone };
export type BjorkPalette = (typeof BJORK_PALETTE)[BjorkTone];

const noopSubscribe = () => () => {};

/** False on the server and the first client render, true after hydration. */
export function useHydrated(): boolean {
  return useSyncExternalStore(
    noopSubscribe,
    () => true,
    () => false,
  );
}

/** Hydration-safe reduced motion: both sides report "not reduced" until mount, then the real value applies. */
export function useReduceMotion(): boolean {
  const hydrated = useHydrated();
  const reduced = useReducedMotion();
  return hydrated && reduced === true;
}

/**
 * Resolves the tone and returns the CSS custom properties for it. Spread `style` on the component root so an
 * explicit `tone` prop wins over the page theme, and status colours (success, warning, error) are always defined.
 */
export function useAiTone(toneProp?: BjorkTone) {
  const tone = useBjorkTone(toneProp);
  const pal = BJORK_PALETTE[tone];
  const light = tone === "light";
  const style = {
    "--bjork-text": pal.text,
    "--bjork-text-medium": pal.textMedium,
    "--bjork-text-muted": pal.textMuted,
    "--bjork-text-soft": pal.textSoft,
    "--bjork-text-faint": pal.textFaint,
    "--bjork-hair": pal.hair,
    "--bjork-border": pal.border,
    "--bjork-border-strong": pal.borderStrong,
    "--bjork-surface": pal.surface,
    "--bjork-raised": pal.raised,
    "--bjork-surface-active": pal.active,
    "--bjork-accent": pal.accent,
    "--bjork-accent-ink": pal.accentInk,
    "--bjork-accent-fill": pal.accentFill,
    "--bjork-accent-soft": pal.accentSoft,
    "--bjork-accent-muted": pal.accentMuted,
    "--bjork-accent-foreground": pal.accentFg,
    "--bjork-success": pal.success,
    "--bjork-warning": pal.warning,
    "--bjork-error": pal.error,
    "--bjork-ring-offset": pal.bg,
    "--bjork-field": light ? "rgba(255, 252, 246, 0.96)" : "rgba(18, 18, 18, 0.95)",
    "--bjork-field-inset": light ? "rgba(239, 231, 216, 0.72)" : "rgba(9, 9, 9, 0.75)",
    "--bjork-menu": light ? "rgba(255, 252, 246, 0.98)" : "rgba(18, 18, 18, 0.98)",
    "--bjork-shadow-menu": light
      ? "inset 0 1px 0 rgba(88, 72, 49, 0.04), inset 0 12px 24px rgba(88, 72, 49, 0.022), 0 22px 44px -26px rgba(66, 52, 33, 0.22)"
      : "inset 0 1px 0 rgba(255, 255, 255, 0.055), inset 0 12px 24px rgba(255, 255, 255, 0.018), 0 22px 42px -22px rgba(0, 0, 0, 0.9)",
    "--bjork-shadow-surface": light
      ? "inset 0 7px 14px rgba(88, 72, 49, 0.045), inset 0 0.5px 0.5px rgba(255, 255, 255, 0.92), 0 14px 22px -9px rgba(66, 52, 33, 0.11)"
      : "inset 0 7px 14px rgba(255, 255, 255, 0.03), inset 0 0.5px 0.5px rgba(255, 255, 255, 0.06), 0 14px 20px -6px rgba(0, 0, 0, 0.45)",
    colorScheme: tone,
  } as CSSProperties;
  return { tone, pal, style };
}

/** Classes for the shared keyboard focus ring. */
export const FOCUS_RING =
  "outline-none focus-visible:ring-2 focus-visible:ring-[color:var(--bjork-accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[color:var(--bjork-ring-offset)]";

/** Classes for the shared press feedback. */
export const PRESS = "transition-transform duration-150 ease-out active:scale-[0.97] motion-reduce:transition-none";

/**
 * Controlled-or-uncontrolled state. Pass `value` to control it; `onChange` fires for every change either way.
 */
export function useControllable<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (next: T) => void,
): [T, (next: T) => void] {
  const controlled = value !== undefined;
  const [inner, setInner] = useState(defaultValue);
  const current = controlled ? value : inner;
  const onChangeRef = useRef(onChange);
  useLayoutEffect(() => {
    onChangeRef.current = onChange;
  });
  const set = useCallback(
    (next: T) => {
      if (!controlled) setInner(next);
      onChangeRef.current?.(next);
    },
    [controlled],
  );
  return [current, set];
}

/** 1234 -> "1,234", 18400 -> "18.4k", 1_200_000 -> "1.2M". */
export function formatTokens(n: number): string {
  if (n < 10_000) return Math.round(n).toLocaleString("en-US");
  if (n < 1_000_000) return `${(n / 1000).toFixed(n < 100_000 ? 1 : 0).replace(/\.0$/, "")}k`;
  return `${(n / 1_000_000).toFixed(n < 10_000_000 ? 2 : 1).replace(/\.?0+$/, "")}M`;
}

/** US dollars with sub-cent precision when it matters: 0.0042 -> "$0.0042", 12.5 -> "$12.50". */
export function formatCost(usd: number): string {
  if (usd === 0) return "$0.00";
  if (Math.abs(usd) < 0.01) return `$${usd.toFixed(4)}`;
  if (Math.abs(usd) < 1) return `$${usd.toFixed(3)}`;
  return `$${usd.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

/** 640 -> "640ms", 4200 -> "4.2s", 95000 -> "1m 35s". */
export function formatDuration(ms: number): string {
  if (ms < 1000) return `${Math.round(ms)}ms`;
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)}s`;
  const m = Math.floor(ms / 60_000);
  const s = Math.round((ms % 60_000) / 1000);
  return `${m}m ${s}s`;
}

/** 2_400_000 bytes -> "2.4 MB". */
export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  const units = ["KB", "MB", "GB"];
  let v = bytes / 1024;
  let i = 0;
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024;
    i++;
  }
  return `${v.toFixed(v < 10 ? 1 : 0)} ${units[i]}`;
}

/** Shimmer keyframes for "working" text. Mount once with <style href=... precedence="default">. */
export const SHIMMER_TEXT_CSS =
  "@keyframes bjork-ai-shimmer{from{background-position:100% 0}to{background-position:0% 0}}" +
  ".bjork-ai-shimmer{background-image:linear-gradient(90deg,var(--bjork-text-muted) 0%,var(--bjork-text-muted) 40%,var(--bjork-text) 50%,var(--bjork-text-muted) 60%,var(--bjork-text-muted) 100%);background-size:300% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:bjork-ai-shimmer 1.8s linear infinite}" +
  "@media (prefers-reduced-motion: reduce){.bjork-ai-shimmer{animation:none;background:none;color:var(--bjork-text-muted)}}";

export type BjorkTone = "dark" | "light";

// Canvas, WebGL and SVG attribute colours. DOM code uses the CSS tokens with these as fallbacks.
export const BJORK_PALETTE = {
  dark: {
    bg: "#050505", stage: "#111111", surface: "#121212", raised: "#161616", active: "#202020",
    border: "#232323", borderStrong: "#343434",
    text: "#ededed", textMedium: "rgba(237,237,237,0.72)", textMuted: "rgba(237,237,237,0.52)",
    textSoft: "rgba(237,237,237,0.36)", textFaint: "rgba(237,237,237,0.22)", hair: "rgba(237,237,237,0.12)",
    accent: "#ec5c13", accentInk: "#ec5c13", accentFill: "#b84a12", accentSoft: "rgba(236,92,19,0.12)", accentMuted: "rgba(236,92,19,0.24)",
    accentFg: "#fff2ea", success: "#4cc38a", warning: "#f2b544", error: "#ff5c4d",
  },
  light: {
    bg: "#f7f5ef", stage: "#f7f5ef", surface: "#fffcf6", raised: "#f5efe3", active: "#efe7d8",
    border: "#eee6db", borderStrong: "#e1d7c8",
    text: "#171717", textMedium: "rgba(23,23,23,0.72)", textMuted: "rgba(23,23,23,0.52)",
    textSoft: "rgba(23,23,23,0.36)", textFaint: "rgba(23,23,23,0.22)", hair: "rgba(23,23,23,0.10)",
    accent: "#ec7d43", accentInk: "#b4531f", accentFill: "#ec7d43", accentSoft: "rgba(236,125,67,0.10)", accentMuted: "rgba(236,125,67,0.20)",
    accentFg: "#3f2112", success: "#1f8a55", warning: "#a86b00", error: "#c8361f",
  },
} as const;

"use client";

import { useSyncExternalStore } from "react";
import { useTheme } from "next-themes";
import type { BjorkTone } from "./palette";

const subscribeNoop = () => () => {};
const getMounted = () => true;
const getServerMounted = () => false;

/**
 * Resolves the tone for a component. An explicit `tone` always wins.
 * Otherwise it follows next-themes' resolved theme, but only after mount,
 * so the server render and first client render agree on dark.
 */
export function useBjorkTone(tone?: BjorkTone): BjorkTone {
  const { resolvedTheme } = useTheme();
  const mounted = useSyncExternalStore(subscribeNoop, getMounted, getServerMounted);
  if (tone) return tone;
  if (!mounted) return "dark";
  return resolvedTheme === "light" ? "light" : "dark";
}

"use client";

import { useLayoutEffect, useRef, useState, type RefObject } from "react";
import { useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { useVisibleLoop } from "@/components/bjork-ui/_core/loop";
import { stepSpring, type SpringState } from "@/components/bjork-ui/_core/spring";
import { easeCss } from "@/components/bjork-ui/_core/motion";

export type StrokeIconName =
  | "menu"
  | "equal"
  | "minus"
  | "plus"
  | "close"
  | "chevron-down"
  | "chevron-up"
  | "chevron-right"
  | "chevron-left"
  | "arrow-right"
  | "arrow-down"
  | "arrow-left"
  | "arrow-up"
  | "check"
  | "play"
  | "pause"
  | "dot"
  | "ellipsis"
  | "busy"
  | (string & {});

// Three line segments in a 24 x 24 box. `hidden` lines render at opacity 0 and collapse
// onto the centroid of the visible endpoints. `group` icons share geometry and only rotate.
export interface StrokeIconDef {
  lines: [number, number, number, number][];
  hidden?: [boolean, boolean, boolean];
  group?: string;
  rotation?: number;
  spin?: boolean;
  strokeScale?: number;
}

export interface StrokeMorphIconProps {
  name: StrokeIconName;
  size?: number;
  strokeWidth?: number;
  color?: string;
  spring?: { stiffness: number; damping: number; mass: number };
  spin?: boolean;
  label?: string;
  className?: string;
}

type Seg = [number, number, number, number];

const DEFAULT_SPRING = { stiffness: 380, damping: 30, mass: 0.7 };
const CROSS_LINES: StrokeIconDef["lines"] = [
